// components/Thumbnail.jsx
import React from 'react';
import './styles/Thumbnail.scss'

function Thumbnail({ src, alt = 'Post Image', title }) {
  const getFallbackImage = (prompt = 'blog') =>
    `https://source.unsplash.com/800x400/?${encodeURIComponent(prompt || 'blog')}`;

  const imageSrc = src || getFallbackImage(title);

  return (
    <div className="thumbnail">
      <img src={imageSrc} alt={alt} className="thumbnail__image" />
    </div>
  );
}

export default Thumbnail;
